mapper.select:
SELECT h.id, h.title, h.class_id, h.course_id, h.deadline, h.max_score, h.create_time, c.class_name, co.course_name, (SELECT COUNT(*) FROM homework_submission WHERE homework_id = h.id AND submit_status IN (1, 2) AND is_deleted = 0 ) AS submit_count, (SELECT COUNT(*) FROM homework_submission WHERE homework_id = h.id AND submit_status IN (1, 2) AND score IS NULL AND is_deleted = 0 ) AS pending_grade_count FROM homework h LEFT JOIN class c ON h.class_id = c.id AND c.is_deleted = 0 LEFT JOIN course co ON h.course_id = co.id AND co.is_deleted = 0 WHERE h.is_deleted = 0
AND h.class_id = #{classId}
AND h.course_id = #{courseId}
ORDER BY h.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM homework h
WHERE h.is_deleted = 0

    AND h.class_id = #{classId}


    AND h.course_id = #{courseId}

